class DifficultyConfig { final String id,label; final double hpMultiplier,damageMultiplier,spawnMultiplier,lootMultiplier; const DifficultyConfig(this.id,this.label,{this.hpMultiplier=1,this.damageMultiplier=1,this.spawnMultiplier=1,this.lootMultiplier=1}); static const easy=DifficultyConfig('easy','Рекрут',hpMultiplier:.78,damageMultiplier:.75,spawnMultiplier:.8,lootMultiplier:.9);static const normal=DifficultyConfig('normal','Ветеран');static const hard=DifficultyConfig('hard','Каратель',hpMultiplier:1.35,damageMultiplier:1.25,spawnMultiplier:1.2,lootMultiplier:1.2);static const hell=DifficultyConfig('hell','Инферно',hpMultiplier:1.75,damageMultiplier:1.6,spawnMultiplier:1.45,lootMultiplier:1.45);static DifficultyConfig byId(String id)=>switch(id){'easy'=>easy,'hard'=>hard,'hell'=>hell,_=>normal}; }
